const assetPath = AssetPath.path || "-";

const targetRaw = asset.getValue(`${assetPath}.Product Count Target`);
const goodCount = msg.productGoodCount || 0;

const lifecycle = asset.getValue(`${assetPath}.Job Lifecycle`).trim().toLowerCase();

const progressPath = `${assetPath}.Job Progress`;


function parseNumberLike(value) {
  const normalized = String(value ?? "").replace(/,/g, "").replace(/\s+/g, " ").trim();
  if (!normalized) return NaN;
  const match = normalized.match(/-?\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : NaN;
}

if (!["load", "unload", "complete"].includes(lifecycle)) {
  await asset.set(progressPath, 0);
  send(msg);
  return;
}

const targetEa = parseNumberLike(targetRaw);
if (!Number.isFinite(targetEa) || targetEa <= 0) {
  await asset.set(progressPath, 0);
  send(msg);
  return;
}

const safeGoodCount = Number.isFinite(goodCount) ? Math.max(0, Math.round(goodCount)) : 0;
const progress = Math.max(0, Math.round((safeGoodCount / targetEa) * 100));

await asset.set(progressPath, progress);

msg.jobProgress = progress;
msg.productGoodCount = safeGoodCount;

send(msg);

const assetPath = AssetPath.path || "-";
const categoryPath = `${assetPath}.Job Activity Category`;
const alarmPath = `${assetPath}.Job Activity Alarm`;
const workOrder = asset.getValue(`${assetPath}.Work Order`).trim();

let activeCategory = "-";
const activeCategories = [];

if (workOrder && workOrder !== "-") {
  // const basePath = `${assetPath}/Job/${workOrder}/Activity`;
  const basePath = `${assetPath}/Job/*/Activity`;

  const [setupOpen, idleOpen, prodOpen] = await Promise.all([
    eventSys.get(`${basePath}/Setup/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Idle/*`, "*", "*", "open", {}, { limit: 200 }),
    eventSys.get(`${basePath}/Production/*`, "*", "*", "open", {}, { limit: 200 })
  ]);

  // console.log(`${basePath}/Setup/*`);
  // console.log(`${basePath}/Idle/*`);
  // console.log(`${basePath}/Production/*`);

  if (setupOpen.length > 0) activeCategories.push("Setup");
  if (idleOpen.length > 0) activeCategories.push("Idle");
  if (prodOpen.length > 0) activeCategories.push("Production");
}

if (activeCategories.length === 1) {
  activeCategory = activeCategories[0];
  await asset.set(categoryPath, activeCategory);
  await asset.set(alarmPath, "-");
} else if (activeCategories.length === 0) {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, "-");
} else {
  await asset.set(categoryPath, "-");
  await asset.set(alarmPath, `!!!Multiple activity categories active: ${activeCategories.join(", ")}!!!`);
}

msg.activityCategory = activeCategory;
msg.activeCategories = activeCategories;

send(msg);

const assetPath = AssetPath.path || "-";
const rawPath = `${assetPath}.Encoder Input Raw Value`;
const prevRawPath = `${assetPath}.Encoder Input Prev Value`;
const totalConsumedPath = `${assetPath}.Total Paper Consumed Input`;

const raw = asset.getValue(rawPath);
const prevRaw = asset.getValue(prevRawPath);
const totalPrev = asset.getValue(totalConsumedPath);

const deltaRaw = raw >= prevRaw ? (raw - prevRaw) : raw;
if (!Number.isFinite(deltaRaw) || deltaRaw < 0) {
  await asset.set(prevRawPath, raw);
  send(msg);
  return;
}

if (deltaRaw === 0) {
  await asset.set(prevRawPath, raw);
  msg.encoderDeltaRaw = 0;
  msg.paperConsumedDelta = 0;
  msg.paperConsumedSource = "input";
  send(msg);
  return;
}

const deltaConsumed = deltaRaw / 100;

await asset.setMany([
  { path: totalConsumedPath, value: totalPrev + deltaConsumed },
  { path: prevRawPath, value: raw }
]);

msg.totalPaperConsumed = totalPrev + deltaConsumed;
msg.encoderDeltaRaw = deltaRaw;
msg.paperConsumedDelta = deltaConsumed;
msg.paperConsumedSource = "input";

send(msg);

const assetPath = AssetPath.path || "-";
const activeCategory = String(msg.activityCategory ?? asset.getValue(`${assetPath}.Job Activity Category`)).trim();

let setupTime = asset.getValue(`${assetPath}.Total Setup Time`);
let idleTime = asset.getValue(`${assetPath}.Total Idle Time`);
let prodTime = asset.getValue(`${assetPath}.Total Production Time`);
let runningHour = asset.getValue(`${assetPath}.Running Hour`);

if (activeCategory === "Setup") setupTime += 1;
else if (activeCategory === "Idle") idleTime += 1;
else if (activeCategory === "Production") prodTime += 1;

if (["Setup", "Idle", "Production"].includes(activeCategory)) {
  runningHour += 1;
}

await asset.set(`${assetPath}.Total Setup Time`, setupTime);
await asset.set(`${assetPath}.Total Idle Time`, idleTime);
await asset.set(`${assetPath}.Total Production Time`, prodTime);
await asset.set(`${assetPath}.Running Hour`, runningHour);

send(msg);

const assetPath = AssetPath.path || "-";
const lifecycle = String(msg.payload?.value ?? "").trim().toLowerCase();
const workOrder = asset.getValue(`${assetPath}.Work Order`).trim();
const alarmPath = `${assetPath}.Job Lifecycle Alarm`;

if (!["load", "unload", "complete", "cancel"].includes(lifecycle)) {
  return;
}

if (!workOrder || workOrder === "-") {
  await asset.set(alarmPath, "!!!No Active Work Order!!!");
  return;
}

if (lifecycle === "load") {
  await asset.set(alarmPath, "-");
  msg.eventRequest = { mode: "open", notes: `${workOrder} loaded` };
  send(["open event"], msg);
  return;
}

if (lifecycle === "cancel") {
  await asset.set(alarmPath, "-");
  msg.eventRequest = { mode: "close", notes: `${workOrder} cancelled` };
  send(["close event"], msg);
  return;
}

if (lifecycle === "complete") {
  await asset.set(alarmPath, "-");
  msg.eventRequest = { mode: "close", notes: `${workOrder} completed` };
  send(["close event"], msg);
}

const assetPath = AssetPath.path || "-";
const rawActivity = String(msg.payload?.value ?? "").trim();
const workOrder = asset.getValue(`${assetPath}.Work Order`).trim();
const alarmPath = `${assetPath}.Job Activity Alarm`;

if (!rawActivity || rawActivity === "-") {
  await asset.set(alarmPath, "-");
  return;
}

if (!workOrder || workOrder === "-") {
  await asset.set(alarmPath, "!!!No Active Work Order!!!");
  return;
}

const parts = rawActivity.split("/").map((item) => item.trim()).filter(Boolean);
const categoryToken = String(parts[0] || "").toLowerCase();
const activityDetail = parts.slice(1).join("/").trim() || "Run";

let templateId = "";

switch (categoryToken) {
  case "production":
    templateId = "template.taiyo.job.activity.production";
    break;
  case "setup":
    templateId = "template.taiyo.job.activity.setup";
    break;
  case "idle":
    templateId = "template.taiyo.job.activity.idle";
    break;
  default:
    await asset.set(alarmPath, `!!!Unknown activity category: ${rawActivity}!!!`);
    return;
}

await asset.set(alarmPath, "-");
msg.eventRequest = {
  mode: "open",
  templateId,
  vars: { activityDetail },
  notes: `${workOrder} ${categoryToken}/${activityDetail} opened`
};

send(msg);

const assetPath = AssetPath.path || "-";
const totalCountPath = `${assetPath}.Product Total Count`;
const goodCountPath = `${assetPath}.Product Good Count`;
const rejectCountPath = `${assetPath}.Product Reject Count`;
const prodConsumed = asset.getValue(`${assetPath}.Paper Consumed Production`);
const rejectCount = asset.getValue(rejectCountPath);
const paperFoldSizeRaw = asset.getValue(`${assetPath}.Paper/Fold Size`);
const countPerFoldRaw = asset.getValue(`${assetPath}.Product Count Per Fold`);

function parseNumberLike(value) {
  const normalized = String(value ?? "").replace(/,/g, "").replace(/\s+/g, " ").trim();
  if (!normalized) return NaN;
  const match = normalized.match(/-?\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : NaN;
}

const paperFoldSize = parseNumberLike(paperFoldSizeRaw);
const countPerFold = parseNumberLike(countPerFoldRaw);

let totalCount = 0;
if (Number.isFinite(prodConsumed) && prodConsumed > 0 && Number.isFinite(paperFoldSize) && paperFoldSize > 0 && Number.isFinite(countPerFold) && countPerFold > 0) {
  totalCount = Math.max(0, Math.round((prodConsumed / (paperFoldSize * 0.01)) * countPerFold));
}

const safeRejectCount = Number.isFinite(rejectCount) ? Math.max(0, Math.round(rejectCount)) : 0;
const goodCount = Math.max(0, totalCount - safeRejectCount);

await asset.setMany([
  { path: totalCountPath, value: totalCount },
  { path: goodCountPath, value: goodCount }
]);

msg.productTotalCount = totalCount;
msg.productRejectCount = safeRejectCount;
msg.productGoodCount = goodCount;

send(msg);

const assetPath = AssetPath.path || "-";
const rawPath = `${assetPath}.Encoder Output Raw Value`;
const prevRawPath = `${assetPath}.Encoder Output Prev Value`;
const totalConsumedPath = `${assetPath}.Total Paper Consumed Output`;

const raw = asset.getValue(rawPath);
const prevRaw = asset.getValue(prevRawPath);
const totalPrev = asset.getValue(totalConsumedPath);

const deltaRaw = raw >= prevRaw ? (raw - prevRaw) : raw;
if (!Number.isFinite(deltaRaw) || deltaRaw < 0) {
  await asset.set(prevRawPath, raw);
  send(msg);
  return;
}

if (deltaRaw === 0) {
  await asset.set(prevRawPath, raw);
  msg.paperConsumedDelta = 0;
  msg.paperConsumedSource = "output";
  send(msg);
  return;
}

const deltaConsumed = deltaRaw / 100;

await asset.setMany([
  { path: totalConsumedPath, value: totalPrev + deltaConsumed },
  { path: prevRawPath, value: raw }
]);

msg.paperConsumedDelta = deltaConsumed;
msg.paperConsumedSource = "output";

send(msg);

const assetPath = AssetPath.path || "-";
const machineSpeedPath = `${assetPath}.Machine Speed`;

const deltaRaw = Number(msg.encoderDeltaRaw ?? NaN);
if (!Number.isFinite(deltaRaw) || deltaRaw < 0) {
  send(msg);
  return;
}

// encoder raw is in cm and trigger runs every second, so m/min = cm/s * 60 / 100 = cm * 0.6
const speedMpm = deltaRaw * 0.6;
await asset.set(machineSpeedPath, speedMpm);

send(msg);

const assetPath = AssetPath.path || "-";

const categoryPath = `${assetPath}.Job Activity Category`;

const setupPath = `${assetPath}.Paper Consumed Setup`;
const idlePath = `${assetPath}.Paper Consumed Idle`;
const prodPath = `${assetPath}.Paper Consumed Production`;
const wastePath = `${assetPath}.Total Paper Waste`;

const totalConsumed = msg.totalPaperConsumed || 0;

const setupPrev = asset.getValue(setupPath);
const idlePrev = asset.getValue(idlePath);
const prodPrev = asset.getValue(prodPath);

let deltaConsumed = Number(msg.paperConsumedDelta ?? NaN);
if (!Number.isFinite(deltaConsumed)) {
  deltaConsumed = totalConsumed - (setupPrev + idlePrev + prodPrev);
}

const activeCategory = String(msg.activityCategory ?? asset.getValue(categoryPath)).trim();

if (!Number.isFinite(deltaConsumed) || deltaConsumed <= 0 || !["Setup", "Idle", "Production"].includes(activeCategory)) {
  send(msg);
  return;
}

let setupNew = setupPrev;
let idleNew = idlePrev;
let prodNew = prodPrev;

if (activeCategory === "Setup") setupNew += deltaConsumed;
else if (activeCategory === "Idle") idleNew += deltaConsumed;
else if (activeCategory === "Production") prodNew += deltaConsumed;

const waste = setupNew + idleNew;

await asset.setMany([
  { path: setupPath, value: setupNew },
  { path: idlePath, value: idleNew },
  { path: prodPath, value: prodNew },
  { path: wastePath, value: waste }
]);

msg.paperConsumedDelta = deltaConsumed;
msg.activityCategory = activeCategory;

msg.paperConsumedSetup = setupNew || 0;
msg.paperConsumedIdle = idleNew || 0;
msg.paperConsumedProduction = prodNew || 0;

send(msg);

